effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1.0 - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.0,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      mat2 r2d(float a) {
      	float c = cos(a), s = sin(a);
      	return mat2(c, s, -s, c);
      }

       vec2 path(float t) {
      	float a;
      	float b;
      	vec2 rpath;

       if( PATT==0 ) { 
       a = 0.0;
       b = 0.0;
       rpath = vec2(0.0, 0.0); }

       else if( PATT==1 ) { 
       a = sin(t*xxa);
       b = sin(t*xxb);
       rpath = vec2(xxc*a, a*b); }

      	return rpath;
      }

      float g = 0.0;
      float de(vec3 p) {
      	p.xy -= path(p.z);

      	float d = -length(p.xy) + SPC;// tunnel (inverted cylinder) /// SPACE
               float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
      	p.xy += vec2(cos(p.z + iTime)*sin(iTime), cos(p.z + iTime));
      	if(bloxx) { p.z -= 6.0 + iTime * 6.0; } // CENTER BLINK PIXEL
      	d = min(d, dot(p, normalize(sign(p))) - 1.0); // octahedron (LJs formula)
      	g += 0.015 / (0.01 + d * d);
      	return d;
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.0,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

      	vec2 uv = umefx;

      	float dt = iTime * 6.0;
      	vec3 ro = vec3(0, 0, -5.0 + dt);
      	vec3 ta = vec3(CAM.x, CAM.y, dt); //CAMERA

      	ro.xy += path(ro.z);
      	ta.xy += path(ta.z);

      	vec3 fwd = normalize(ta - ro);
      	vec3 right = cross(fwd, vec3(0, 1, 0));
      	vec3 up = cross(right, fwd);
      	vec3 rd = normalize(fwd + uv.x*right + uv.y*up);

      	rd.xy *= r2d(sin(-ro.x / 3.14)*0.3);

      	vec3 p = floor(ro) + 0.5;
      	vec3 mask;
      	vec3 drd = 1.0 / abs(rd);
      	rd = sign(rd);
      	vec3 side = drd * (rd * (p - ro) + 0.5); // SMOOTH

      	float t = 0.0, ri = 0.0;
      	for (float i = 0.0; i < 1.0; i += 0.01) {
      		ri = i;

      		if (de(p) < 0.0) break;// distance field

      		mask = step(side, side.yzx) * step(side, side.zxy);

      		side += drd * mask;
      		p += rd * mask;
      	}
      	t = length(p - ro);

      	vec3 c = vec3(1) * length(mask * vec3(color1.rgb));
      	// vec3 c = vec3(1) * length(mask * vec3(1.0, 0.5, 0.75));
      	c = mix(vec3(color2.rgb), vec3(color3.rgb), c);
      	// c = mix(vec3(0.2, 0.2, 0.7), vec3(0.2, 0.1, 0.2), c);
      	c += g * GAM; // GAMMA

                if( CHAN==0 ) { c.r += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }
                else if( CHAN==1 ) { c.g += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }
                else if( CHAN==2 ) { c.b += sin(iTime)*0.2 + sin(p.z*0.5 - iTime * 6.0); }

      	c = mix(c, vec3(color4.rgb), 1.0 - exp(-0.001*t*t));// fog
      	// c = mix(c, vec3(0.2, 0.1, 0.2), 1.0 - exp(-0.001*t*t));// fog

      	fragColor = vec4(c, 1.0);

 	      vec4 factor = mix(texColorX,fragColor,1.0);
 	      // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	      // factor = mix(texColorX,gradmap,1.0);

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
